import java.util.concurrent.*;
public class Main {public static void main(String[]a)throws Exception{BlockingQueue<Integer> q=new ArrayBlockingQueue<>(3);Thread producer=new Thread(()->{try{for(int i=1;i<=5;i++){q.put(i);System.out.println("Produced "+i);}q.put(-1);}catch(InterruptedException e){Thread.currentThread().interrupt();}});Thread consumer=new Thread(()->{try{int x;while((x=q.take())!=-1)System.out.println("Consumed "+x);}catch(InterruptedException e){Thread.currentThread().interrupt();}});producer.start();consumer.start();producer.join();consumer.join();System.out.println("Completed without busy waiting");}}
